import { isStandalone } from '../dev/isStandalone';

/**
 * Task MFE standalone (`Linm.Web.Task` `yarn start:std`).
 * :9302 is Gis — not Platform Task.
 */
export const PLATFORM_TASK_STD_ORIGIN =
  import.meta.env.VITE_PLATFORM_TASK_STD_URL || 'http://localhost:8608';

export const PLATFORM_TASK_LIST_PATH = '/platform-task/cv';

export function platformTaskListHref(): string {
  return `${PLATFORM_TASK_STD_ORIGIN}${PLATFORM_TASK_LIST_PATH}`;
}

export function platformTaskDetailPath(
  taskId: string,
  from: string,
  sourceId: string,
): string {
  const qs = new URLSearchParams({ from, sourceId });
  return `${PLATFORM_TASK_LIST_PATH}/${encodeURIComponent(taskId)}?${qs}`;
}

/** Shell path on host; absolute Task origin when Field is standalone (:9304). */
export function platformTaskDetailHref(
  taskId: string,
  from: string,
  sourceId: string,
): string {
  const path = platformTaskDetailPath(taskId, from, sourceId);
  return isStandalone ? `${PLATFORM_TASK_STD_ORIGIN}${path}` : path;
}
