/**
 * Platform Task create — cite Medical BFF `/tasks` (P1 · GAP-RTI-BFF-01).
 * Body origin quad — cấm parentEntity / parentId / domainSource.
 */

import { apiClient, unwrap } from '../api';
import type { BffResponse } from '../api';
import { RMMS_TASK_SYSTEM_CODE } from './origin';
import type { CreateTaskIntegrationRequest } from './requestModel';
import type { TaskDto } from './responseModel';

export const taskEndpoint = {
  createTask: async (data: CreateTaskIntegrationRequest): Promise<TaskDto> => {
    const payload: Record<string, unknown> = {
      title: data.title,
      description: data.description ?? '',
      priority: data.priority,
      assignmentStrategy: data.assignmentStrategy,
      estimatedHours: 0,
      skillsRequired: [],
      tags: [],
      dueDate: data.dueDate || undefined,
      assigneeId: data.assigneeId || undefined,
      assigneeName: data.assigneeName || undefined,
      systemCode: data.systemCode || RMMS_TASK_SYSTEM_CODE,
      source: data.source,
      sourceEntityType: data.sourceEntityType,
      sourceEntityId: data.sourceEntityId,
    };
    const res = await apiClient.post<BffResponse<TaskDto>>('/tasks', payload);
    return unwrap(res);
  },
};
