import React, { useEffect, useRef, useState } from 'react';
import {
  mountParcel,
  unmountParcel,
} from '@linm-soft-org/linm-web-common-components';
import type { Parcel } from 'single-spa';
import { RMMS_TASK_SYSTEM_CODE } from '../../services/task/origin';
import {
  CHAT_SECTION_PARCEL,
  RMMS_MESSAGE_PREFIX_MAP,
  RMMS_MESSAGE_ROUTE_MAP,
  RMMS_MESSAGE_SYSTEM_ROUTE_MAP,
} from '../../parcels/messageParcelConfig';
import styles from './ChatSectionHost.module.css';

export interface ChatSectionHostProps {
  taskId: string;
  onNavigate: (path: string) => void;
}

export const ChatSectionHost: React.FC<ChatSectionHostProps> = ({ taskId, onNavigate }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [failed, setFailed] = useState(false);

  useEffect(() => {
    if (!taskId) return;
    setFailed(false);

    let cancelled = false;
    let parcel: Parcel | null = null;

    const timer = window.setTimeout(() => {
      const host = containerRef.current;
      if (!host) return;
      void mountParcel({
        link: CHAT_SECTION_PARCEL,
        domElement: host,
        customProps: {
          entityType: 'task',
          entityId: taskId,
          onNavigate,
          mode: 'both',
          routeMap: RMMS_MESSAGE_ROUTE_MAP,
          systemRouteMap: RMMS_MESSAGE_SYSTEM_ROUTE_MAP,
          systemCode: RMMS_TASK_SYSTEM_CODE,
          prefixMap: RMMS_MESSAGE_PREFIX_MAP,
        },
      })
        .then((p) => {
          if (cancelled) {
            void unmountParcel(p);
            return;
          }
          parcel = p;
        })
        .catch(() => {
          if (!cancelled) setFailed(true);
        });
    }, 0);

    return () => {
      cancelled = true;
      window.clearTimeout(timer);
      void unmountParcel(parcel);
    };
  }, [taskId, onNavigate]);

  if (failed) {
    return (
      <div className={styles.fallback} role="alert">
        <i className="fas fa-comments" />
        <span>
          Không tải được ChatSectionParcel. Chạy Message MFE <code>yarn start</code> (:8506) rồi tải
          lại.
        </span>
      </div>
    );
  }

  return <div ref={containerRef} className={styles.host} data-testid="field-chat-section-host" />;
};

export default ChatSectionHost;
