import { useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import { navigateToUrl } from 'single-spa';
import { isStandalone } from '../dev/isStandalone';

export type InAppNavigateFn = (
  to: string,
  options?: { replace?: boolean; state?: unknown },
) => void;

export type InAppNavigateOptions = {
  replace?: boolean;
  state?: unknown;
};

/** Same-prefix Field MFE: MemoryRouter paths are already shell URLs. */
export function toInAppPath(path: string): string {
  return path.startsWith('/') ? path : `/${path}`;
}

/**
 * List → form in Root shell must update `window.location`.
 * Memory-only `useNavigate` is reset by MemoryRouterSync on `single-spa:routing-event`.
 * Rule: web-app/rule/mfe-run-modes.md · ROUTER-P1-01
 */
export function navigateInAppPath(
  path: string,
  navigate: InAppNavigateFn,
  options?: InAppNavigateOptions,
): void {
  const memoryPath = toInAppPath(path);
  const shellPath = toInAppPath(path);

  if (isStandalone) {
    navigate(memoryPath, { replace: options?.replace, state: options?.state });
    return;
  }

  if (options?.state !== undefined) {
    navigate(memoryPath, { replace: options?.replace ?? true, state: options.state });
    const current = window.location.pathname + window.location.search;
    if (current !== shellPath) {
      window.history.replaceState(null, '', shellPath);
    }
    return;
  }

  navigateToUrl(shellPath);
}

export function useInAppNavigate(): InAppNavigateFn {
  const navigate = useNavigate();
  return useCallback(
    (path: string, options?: InAppNavigateOptions) => {
      navigateInAppPath(path, navigate, options);
    },
    [navigate],
  );
}
