import React, { useCallback, useEffect, useMemo, useState } from 'react';
import { createPortal } from 'react-dom';
import {
  Button,
  LeaveConfirmModal,
  localInputToISOWithOffset,
  useAppToast,
  useLeaveConfirm,
  utcToLocalInputValue,
} from '@linm-soft-org/linm-web-common-components';
import { severityLabel } from '../../demo/incidentStore';
import { RMMS_TASK_SYSTEM_CODE, taskService } from '../../services/task';
import type {
  AssignmentStrategy,
  CreateTaskIntegrationRequest,
  SourceEntityType,
  TaskPriority,
} from '../../services/task/requestModel';
import type { TaskDto } from '../../services/task/responseModel';
import { navigateToCreatedTask } from '../../utils/taskPostNavigate';
import styles from './GiaoViecModal.module.css';

const TEST_ID = 'rmms-giao-viec-modal';

const PRIORITY_OPTIONS: { value: TaskPriority; label: string }[] = [
  { value: 'critical', label: 'Khẩn cấp (critical)' },
  { value: 'high', label: 'Cao (high)' },
  { value: 'medium', label: 'Trung bình (medium)' },
  { value: 'low', label: 'Thấp (low)' },
];

const STRATEGY_OPTIONS: { value: AssignmentStrategy; label: string }[] = [
  { value: 'pool', label: 'Pool' },
  { value: 'direct', label: 'Trực tiếp (direct)' },
  { value: 'team', label: 'Team' },
];

function isGuid(value: string): boolean {
  return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value.trim());
}

function stampDescription(
  note: string,
  route: string,
  chainage: string,
  hangMuc: string,
  team: string,
): string {
  const parts = [note.trim()].filter((part) => part.length > 0);
  if (route.trim()) parts.push(`tuyen=${route.trim()}`);
  if (chainage.trim()) parts.push(`lyTrinh=${chainage.trim()}`);
  if (hangMuc.trim()) parts.push(`hangMuc=${hangMuc.trim()}`);
  if (team.trim()) parts.push(`doi=${team.trim()}`);
  return parts.join('\n');
}

export interface GiaoViecContextPatrol {
  source: 'patrol';
  sourceEntityType: 'patrol_session';
  sourceEntityId: string;
  sessionCode: string;
  route: string;
  title: string;
  description?: string;
  priority: TaskPriority;
  assignmentStrategy: AssignmentStrategy;
  dueDate: string;
}

export interface GiaoViecContextIncident {
  source: 'incident';
  sourceEntityType: 'incident';
  sourceEntityId: string;
  incidentCode: string;
  title: string;
  severity: string;
  description?: string;
  priority: TaskPriority;
  assignmentStrategy: AssignmentStrategy;
  dueDate: string;
}

export interface GiaoViecContextOps {
  source: 'ops';
  sourceEntityType: 'ops_directive';
  sourceEntityId: string;
  opsCode: string;
  title: string;
  priorityLabel?: string;
  description?: string;
  priority: TaskPriority;
  assignmentStrategy: AssignmentStrategy;
  dueDate: string;
}

export type GiaoViecContext = GiaoViecContextPatrol | GiaoViecContextIncident | GiaoViecContextOps;

export interface GiaoViecModalProps {
  open: boolean;
  context: GiaoViecContext | null;
  onClose: () => void;
  /** Stay on Field + open ChatSectionParcel. Omit = navigate to Task MFE. */
  onCreated?: (task: TaskDto, context: GiaoViecContext) => void;
}

export const GiaoViecModal: React.FC<GiaoViecModalProps> = ({
  open,
  context,
  onClose,
  onCreated,
}) => {
  const toast = useAppToast();
  const [title, setTitle] = useState('');
  const [description, setDescription] = useState('');
  const [priority, setPriority] = useState<TaskPriority>('high');
  const [assignmentStrategy, setAssignmentStrategy] = useState<AssignmentStrategy>('pool');
  const [dueDate, setDueDate] = useState('');
  const [assigneeId, setAssigneeId] = useState('');
  const [assigneeName, setAssigneeName] = useState('');
  const [routeName, setRouteName] = useState('');
  const [chainage, setChainage] = useState('');
  const [hangMuc, setHangMuc] = useState('');
  const [teamName, setTeamName] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [dirty, setDirty] = useState(false);

  const { guardedNavigate, leaveConfirmModalProps } = useLeaveConfirm({
    isDirty: dirty,
    title: 'Bỏ thay đổi?',
    message: 'Thông tin giao việc chưa được tạo. Đóng modal?',
  });

  useEffect(() => {
    if (!open || !context) return;
    setTitle(context.title);
    setDescription(context.description ?? '');
    setPriority(context.priority);
    setAssignmentStrategy(context.assignmentStrategy);
    setDueDate(utcToLocalInputValue(context.dueDate));
    setAssigneeId('');
    setAssigneeName('');
    setRouteName(context.source === 'patrol' ? context.route : '');
    setChainage('');
    setHangMuc('');
    setTeamName('');
    setDirty(false);
    setSubmitting(false);
  }, [open, context]);

  const modalTitle = useMemo(() => {
    if (!context) return 'Giao việc';
    if (context.source === 'patrol') return 'Giao việc — Xử lý từ tuần tra';
    if (context.source === 'incident') return 'Giao việc — Xử lý từ sự cố';
    return 'Giao việc — Từ chỉ đạo';
  }, [context]);

  const requestClose = useCallback(() => {
    guardedNavigate(onClose);
  }, [guardedNavigate, onClose]);

  const handleSubmit = async () => {
    if (!context) return;
    const trimmedTitle = title.trim();
    if (!trimmedTitle) {
      toast.warning('Tiêu đề không được để trống.');
      return;
    }
    if (!dueDate) {
      toast.warning('Hạn xử lý không được để trống.');
      return;
    }

    const assigneeGuid = isGuid(assigneeId) ? assigneeId.trim() : undefined;
    const payload: CreateTaskIntegrationRequest = {
      title: trimmedTitle,
      description: stampDescription(description, routeName, chainage, hangMuc, teamName),
      priority,
      assignmentStrategy: assigneeGuid ? 'direct' : assignmentStrategy,
      dueDate: localInputToISOWithOffset(dueDate),
      assigneeId: assigneeGuid,
      assigneeName: assigneeName.trim() || undefined,
      systemCode: RMMS_TASK_SYSTEM_CODE,
      source: context.source,
      sourceEntityType: context.sourceEntityType as SourceEntityType,
      sourceEntityId: context.sourceEntityId,
    };

    setSubmitting(true);
    try {
      const created = await taskService.create(payload);
      toast.success('Đã tạo công việc thành công.');
      setDirty(false);
      onClose();
      if (onCreated) {
        onCreated(created, context);
        return;
      }
      navigateToCreatedTask(created.id, context.source, context.sourceEntityId);
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Không tạo được công việc.');
    } finally {
      setSubmitting(false);
    }
  };

  if (!open || !context) return null;

  return createPortal(
    <>
      <div
        className={styles.giaoViecOverlay}
        data-des-id="DES-RTI-MODAL"
        data-testid={`${TEST_ID}-overlay`}
        onClick={(e) => {
          if (e.target === e.currentTarget) requestClose();
        }}
      >
        <div className={styles.modal} role="dialog" aria-modal="true" aria-labelledby={`${TEST_ID}-title`}>
          <div className={styles.header} id={`${TEST_ID}-title`}>
            {modalTitle}
          </div>
          <div className={styles.contextStrip}>
            {context.source === 'patrol' ? (
              <>
                <span>
                  <strong>Mã ca:</strong> {context.sessionCode}
                </span>
                <span>
                  <strong>Tuyến:</strong> {context.route}
                </span>
              </>
            ) : context.source === 'incident' ? (
              <>
                <span>
                  <strong>Mã VĐ:</strong> {context.incidentCode}
                </span>
                <span>
                  <strong>Mức độ:</strong>{' '}
                  <span className={styles.severityChip}>{severityLabel(context.severity)}</span>
                </span>
              </>
            ) : (
              <>
                <span>
                  <strong>Mã CĐ:</strong> {context.opsCode}
                </span>
                {context.priorityLabel ? (
                  <span>
                    <strong>Ưu tiên:</strong>{' '}
                    <span className={styles.severityChip}>{context.priorityLabel}</span>
                  </span>
                ) : null}
              </>
            )}
          </div>
          <div className={styles.body}>
            <div className={styles.field}>
              <label htmlFor={`${TEST_ID}-title-input`}>Tiêu đề *</label>
              <input
                id={`${TEST_ID}-title-input`}
                value={title}
                onChange={(e) => {
                  setDirty(true);
                  setTitle(e.target.value);
                }}
                data-testid={`${TEST_ID}-title`}
              />
            </div>
            <div className={styles.field}>
              <label htmlFor={`${TEST_ID}-description`}>Ghi chú</label>
              <textarea
                id={`${TEST_ID}-description`}
                rows={2}
                value={description}
                placeholder="Ghi chú từ ca / sự cố…"
                onChange={(e) => {
                  setDirty(true);
                  setDescription(e.target.value);
                }}
                data-testid={`${TEST_ID}-description`}
              />
            </div>
            <div className={styles.row2}>
              <div className={styles.field}>
                <label htmlFor={`${TEST_ID}-priority`}>Ưu tiên *</label>
                <select
                  id={`${TEST_ID}-priority`}
                  value={priority}
                  onChange={(e) => {
                    setDirty(true);
                    setPriority(e.target.value as TaskPriority);
                  }}
                  data-testid={`${TEST_ID}-priority`}
                >
                  {PRIORITY_OPTIONS.map((o) => (
                    <option key={o.value} value={o.value}>
                      {o.label}
                    </option>
                  ))}
                </select>
              </div>
              <div className={styles.field}>
                <label htmlFor={`${TEST_ID}-strategy`}>Cách gán *</label>
                <select
                  id={`${TEST_ID}-strategy`}
                  value={assignmentStrategy}
                  onChange={(e) => {
                    setDirty(true);
                    setAssignmentStrategy(e.target.value as AssignmentStrategy);
                  }}
                  data-testid={`${TEST_ID}-strategy`}
                >
                  {STRATEGY_OPTIONS.map((o) => (
                    <option key={o.value} value={o.value}>
                      {o.label}
                    </option>
                  ))}
                </select>
              </div>
            </div>
            <div className={styles.row2}>
              <div className={styles.field}>
                <label htmlFor={`${TEST_ID}-assignee-id`}>Mã người nhận</label>
                <input
                  id={`${TEST_ID}-assignee-id`}
                  value={assigneeId}
                  placeholder="GUID người nhận"
                  onChange={(e) => {
                    setDirty(true);
                    setAssigneeId(e.target.value);
                  }}
                  data-testid={`${TEST_ID}-assignee-id`}
                />
              </div>
              <div className={styles.field}>
                <label htmlFor={`${TEST_ID}-assignee-name`}>Tên người nhận</label>
                <input
                  id={`${TEST_ID}-assignee-name`}
                  value={assigneeName}
                  onChange={(e) => {
                    setDirty(true);
                    setAssigneeName(e.target.value);
                  }}
                  data-testid={`${TEST_ID}-assignee-name`}
                />
              </div>
            </div>
            <div className={styles.row2}>
              <div className={styles.field}>
                <label htmlFor={`${TEST_ID}-route`}>Tuyến</label>
                <input
                  id={`${TEST_ID}-route`}
                  value={routeName}
                  onChange={(e) => {
                    setDirty(true);
                    setRouteName(e.target.value);
                  }}
                  data-testid={`${TEST_ID}-route`}
                />
              </div>
              <div className={styles.field}>
                <label htmlFor={`${TEST_ID}-chainage`}>Lý trình</label>
                <input
                  id={`${TEST_ID}-chainage`}
                  value={chainage}
                  onChange={(e) => {
                    setDirty(true);
                    setChainage(e.target.value);
                  }}
                  data-testid={`${TEST_ID}-chainage`}
                />
              </div>
            </div>
            <div className={styles.row2}>
              <div className={styles.field}>
                <label htmlFor={`${TEST_ID}-hang-muc`}>Hạng mục</label>
                <input
                  id={`${TEST_ID}-hang-muc`}
                  value={hangMuc}
                  onChange={(e) => {
                    setDirty(true);
                    setHangMuc(e.target.value);
                  }}
                  data-testid={`${TEST_ID}-hang-muc`}
                />
              </div>
              <div className={styles.field}>
                <label htmlFor={`${TEST_ID}-team`}>Đội</label>
                <input
                  id={`${TEST_ID}-team`}
                  value={teamName}
                  onChange={(e) => {
                    setDirty(true);
                    setTeamName(e.target.value);
                  }}
                  data-testid={`${TEST_ID}-team`}
                />
              </div>
            </div>
            <div className={styles.field}>
              <label htmlFor={`${TEST_ID}-dueDate`}>Hạn xử lý *</label>
              <input
                id={`${TEST_ID}-dueDate`}
                type="datetime-local"
                value={dueDate}
                onChange={(e) => {
                  setDirty(true);
                  setDueDate(e.target.value);
                }}
                data-testid={`${TEST_ID}-dueDate`}
              />
            </div>
            <input type="hidden" data-testid={`${TEST_ID}-system-code`} value={RMMS_TASK_SYSTEM_CODE} readOnly />
            <input type="hidden" data-testid={`${TEST_ID}-source`} value={context.source} readOnly />
            <input
              type="hidden"
              data-testid={`${TEST_ID}-source-entity-type`}
              value={context.sourceEntityType}
              readOnly
            />
            <input
              type="hidden"
              data-testid={`${TEST_ID}-source-entity-id`}
              value={context.sourceEntityId}
              readOnly
            />
          </div>
          <div className={styles.footer}>
            <Button variant="secondary" onClick={requestClose} data-testid={`${TEST_ID}-cancel`}>
              Hủy
            </Button>
            <Button
              variant="primary"
              loading={submitting}
              onClick={() => void handleSubmit()}
              data-testid={`${TEST_ID}-confirm`}
            >
              Tạo CV
            </Button>
          </div>
        </div>
      </div>
      <LeaveConfirmModal {...leaveConfirmModalProps} />
    </>,
    document.body,
  );
};

export default GiaoViecModal;
