import { navigateToUrl } from 'single-spa';
import type { DomainSource } from '../services/task/requestModel';
import { platformTaskDetailHref } from './platformTaskUrls';

/** DES-RTI-NAV — post-create: shell `/platform-task/cv/:id` or Task standalone :8608. */
export function navigateToCreatedTask(
  taskId: string,
  from: DomainSource,
  sourceId: string,
): void {
  const href = platformTaskDetailHref(taskId, from, sourceId);
  if (/^https?:\/\//i.test(href)) {
    window.location.assign(href);
    return;
  }
  navigateToUrl(href);
}
